import random

class MusicPlayer:
    def __init__(self):
        self._playlist = []
        self._current_song = None
        self._volume = 50

    @property
    def playlist(self):
        return list(self._playlist)

    @property
    def current_song(self):
        return self._current_song

    @property
    def volume(self):
        return self._volume

    def add_song(self, song):
        self._playlist.append(song)

    def remove_song(self, song):
        if song in self._playlist:
            self._playlist.remove(song)
            if self._current_song == song:
                self.stop()

    def play(self):
        if self._current_song:
            return self._current_song
        elif self._playlist:
            self._current_song = self._playlist[0]
            return self._current_song
        else:
            return False

    def stop(self):
        if self._current_song is None:
            return False
        self._current_song = None
        return True

    def switch_song(self):
        if self._current_song is None:
            return False
        current_index = self._get_current_index()
        if self._has_next_song(current_index):
            self._advance_to_next_song(current_index)
            return True
        return False

    def previous_song(self):
        if self._current_song is None:
            return False
        current_index = self._get_current_index()
        if self._has_previous_song(current_index):
            self._rewind_to_previous_song(current_index)
            return True
        return False

    def set_volume(self, volume):
        if 0 <= volume <= 100:
            self._volume = volume
            return True
        return False

    def shuffle(self):
        if not self._playlist:
            return False
        random.shuffle(self._playlist)
        return True

    def _get_current_index(self):
        return self._playlist.index(self._current_song)

    def _has_next_song(self, current_index):
        return current_index < len(self._playlist) - 1

    def _has_previous_song(self, current_index):
        return current_index > 0

    def _advance_to_next_song(self, current_index):
        self._current_song = self._playlist[current_index + 1]

    def _rewind_to_previous_song(self, current_index):
        self._current_song = self._playlist[current_index - 1]

    def _is_volume_valid(self, volume):
        return 0 <= volume <= 100
